{"sql": "CREATE OR REPLACE FUNCTION transfer_parts(
    source_inv_id INTEGER,
    target_inv_id INTEGER,
    part_num VARCHAR,
    color_id INTEGER,
    qty INTEGER,
    reason VARCHAR DEFAULT 'manual_transfer'
) RETURNS TEXT AS $$
DECLARE
    src_qty INTEGER;
    src_spare BOOLEAN;
    tgt_qty INTEGER;
    msg TEXT;
BEGIN
    -- Validate basic requirements
    IF source_inv_id = target_inv_id THEN
        RETURN 'Error: Cannot transfer to same inventory';
    END IF;

    IF qty < 1 THEN
        RETURN 'Error: Minimum quantity is 1';
    END IF;

    IF qty > 500 THEN
        RETURN 'Error: Maximum quantity is 500';
    END IF;

    -- Check if inventories exist
    IF NOT EXISTS(SELECT 1 FROM lego_inventories WHERE id = source_inv_id) THEN
        RETURN 'Error: Source inventory not found';
    END IF;

    IF NOT EXISTS(SELECT 1 FROM lego_inventories WHERE id = target_inv_id) THEN
        RETURN 'Error: Target inventory not found';
    END IF;

    -- Check if part and color exist
    IF NOT EXISTS(SELECT 1 FROM lego_parts WHERE part_num = part_num) THEN
        RETURN 'Error: Part not found';
    END IF;

    IF NOT EXISTS(SELECT 1 FROM lego_colors WHERE id = color_id) THEN
        RETURN 'Error: Color not found';
    END IF;

    -- Get source inventory details
    SELECT quantity, is_spare INTO src_qty, src_spare
    FROM lego_inventory_parts
    WHERE inventory_id = source_inv_id
    AND part_num = part_num
    AND color_id = color_id;

    IF src_qty IS NULL THEN
        RETURN 'Error: Part not found in source inventory';
    END IF;

    IF src_qty < qty THEN
        RETURN 'Error: Insufficient quantity';
    END IF;

    -- Perform transfer
    BEGIN
        -- Update source
        IF src_qty = qty THEN
            DELETE FROM lego_inventory_parts
            WHERE inventory_id = source_inv_id
            AND part_num = part_num
            AND color_id = color_id;
        ELSE
            UPDATE lego_inventory_parts
            SET quantity = quantity - qty
            WHERE inventory_id = source_inv_id
            AND part_num = part_num
            AND color_id = color_id;
        END IF;

        -- Update target
        SELECT quantity INTO tgt_qty
        FROM lego_inventory_parts
        WHERE inventory_id = target_inv_id
        AND part_num = part_num
        AND color_id = color_id
        AND is_spare = src_spare;

        IF tgt_qty IS NULL THEN
            INSERT INTO lego_inventory_parts (inventory_id, part_num, color_id, quantity, is_spare)
            VALUES (target_inv_id, part_num, color_id, qty, src_spare);
        ELSE
            UPDATE lego_inventory_parts
            SET quantity = quantity + qty
            WHERE inventory_id = target_inv_id
            AND part_num = part_num
            AND color_id = color_id
            AND is_spare = src_spare;
        END IF;

        -- Log transfer
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status
        ) VALUES (
            source_inv_id, target_inv_id, part_num, color_id, qty, reason, 'success'
        );

        msg := 'Successfully transferred ' || qty || ' parts (' || part_num || 
               ', color_id: ' || color_id || ') from inventory ' || source_inv_id || 
               ' to inventory ' || target_inv_id || '. Reason: ' || reason;

